from typing import List
from collections import deque

def maxDistance(grid: List[List[int]]) -> int:
    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Find all land cells and add them to the queue
    queue = deque()
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                queue.append((i, j))

    # If there are no land cells or no water cells, return -1
    if not queue or len(queue) == n * n:
        return -1

    # Perform BFS to find the maximum distance from any land cell to a water cell
    max_dist = 0
    while queue:
        size = len(queue)
        for _ in range(size):
            x, y = queue.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 0:
                    grid[nx][ny] = 1  # Mark as visited
                    queue.append((nx, ny))
        max_dist += 1

    return max_dist - 1  # Subtract 1 because the last increment happens after the last level of BFS
